DO $$ BEGIN IF (SELECT count(*) FROM public.schema_data_exceptions WHERE version=1 AND status='open' AND exception_class='pre_anchor_blocking') > 0 THEN RAISE EXCEPTION 'pre_anchor_blocking'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='users__birthday_type_domain__check') THEN ALTER TABLE public."users" ADD CONSTRAINT "users__birthday_type_domain__check" CHECK ((birthday_type IS NULL OR birthday_type IN ('SOLAR','LUNAR'))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='users__email_canonical_nonblank__check') THEN ALTER TABLE public."users" ADD CONSTRAINT "users__email_canonical_nonblank__check" CHECK ((email IS NULL OR btrim(email)<>'')); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='users__phone_canonical_format__check') THEN ALTER TABLE public."users" ADD CONSTRAINT "users__phone_canonical_format__check" CHECK ((phone_canonical IS NULL OR phone_canonical ~ '^[0-9]{10,11}$')); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='users__phone_canonical_source_valid__check') THEN ALTER TABLE public."users" ADD CONSTRAINT "users__phone_canonical_source_valid__check" CHECK ((phone_number IS NULL OR btrim(phone_number)='' OR phone_canonical IS NOT NULL)); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='categories__badge_variant_domain__check') THEN ALTER TABLE public."categories" ADD CONSTRAINT "categories__badge_variant_domain__check" CHECK ((badge_variant IN ('default','secondary','destructive','outline'))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='categories__sort_order_nonnegative__check') THEN ALTER TABLE public."categories" ADD CONSTRAINT "categories__sort_order_nonnegative__check" CHECK ((sort_order >= 0)); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='alumni_database__mobile_canonical_format__check') THEN ALTER TABLE public."alumni_database" ADD CONSTRAINT "alumni_database__mobile_canonical_format__check" CHECK ((mobile_canonical IS NULL OR mobile_canonical ~ '^[0-9]{10,11}$')); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='alumni_database__mobile_canonical_source_valid__check') THEN ALTER TABLE public."alumni_database" ADD CONSTRAINT "alumni_database__mobile_canonical_source_valid__check" CHECK ((mobile IS NULL OR btrim(mobile)='' OR mobile_canonical IS NOT NULL)); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='community_events__event_type_domain__check') THEN ALTER TABLE public."community_events" ADD CONSTRAINT "community_events__event_type_domain__check" CHECK ((event_type IN ('obituary','wedding','opening','other'))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='community_events__status_domain__check') THEN ALTER TABLE public."community_events" ADD CONSTRAINT "community_events__status_domain__check" CHECK ((status IN ('draft','published'))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='event_parse_rate_limits__request_count_nonnegative__check') THEN ALTER TABLE public."event_parse_rate_limits" ADD CONSTRAINT "event_parse_rate_limits__request_count_nonnegative__check" CHECK ((request_count >= 0)); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='event_parse_rate_limits__updated_after_window_start__check') THEN ALTER TABLE public."event_parse_rate_limits" ADD CONSTRAINT "event_parse_rate_limits__updated_after_window_start__check" CHECK ((updated_at >= window_started_at)); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='pending_registrations__email_canonical_nonblank__check') THEN ALTER TABLE public."pending_registrations" ADD CONSTRAINT "pending_registrations__email_canonical_nonblank__check" CHECK ((btrim(email)<>'')); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='pending_registrations__status_domain__check') THEN ALTER TABLE public."pending_registrations" ADD CONSTRAINT "pending_registrations__status_domain__check" CHECK ((status IN ('pending','approved','rejected'))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='kakao_oauth_states__expiry_after_start__check') THEN ALTER TABLE public."kakao_oauth_states" ADD CONSTRAINT "kakao_oauth_states__expiry_after_start__check" CHECK ((expires_at > started_at)); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='payments__amount_positive__check') THEN ALTER TABLE public.payments ADD CONSTRAINT "payments__amount_positive__check" CHECK ((amount > 0)) NOT VALID; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.schema_data_exceptions WHERE version=1 AND status='open' AND rule_code='payments.amount_positive') THEN ALTER TABLE public.payments VALIDATE CONSTRAINT "payments__amount_positive__check"; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='payments__status_domain__check') THEN ALTER TABLE public.payments ADD CONSTRAINT "payments__status_domain__check" CHECK ((status IN ('pending','completed','failed'))) NOT VALID; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.schema_data_exceptions WHERE version=1 AND status='open' AND rule_code='payments.status_domain') THEN ALTER TABLE public.payments VALIDATE CONSTRAINT "payments__status_domain__check"; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='payments__type_domain__check') THEN ALTER TABLE public.payments ADD CONSTRAINT "payments__type_domain__check" CHECK ((type IN ('연회비','기타'))) NOT VALID; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.schema_data_exceptions WHERE version=1 AND status='open' AND rule_code='payments.type_domain') THEN ALTER TABLE public.payments VALIDATE CONSTRAINT "payments__type_domain__check"; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='payments__year_domain__check') THEN ALTER TABLE public.payments ADD CONSTRAINT "payments__year_domain__check" CHECK ((year BETWEEN 2024 AND 2100)) NOT VALID; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.schema_data_exceptions WHERE version=1 AND status='open' AND rule_code='payments.year_domain') THEN ALTER TABLE public.payments VALIDATE CONSTRAINT "payments__year_domain__check"; END IF; END $$;
